{"path": "site/spoken-answer.mjs", "text": "// Codex bounded D04 assistance: formatting only, no semantic summary.
// Prefer the complete answer: a spoken summary may omit errors or reservations.
// JARVIS D04: daily mode omits paths/IDs unless detailed=true, preserves errors/reservations.

function removeMarkdown(text) {
  return text.split('\n').map(line => {
    if (/^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line)) return '';
    return line.replace(/^\s{0,3}#{1,6}\s+/, '')
      .replace(/^\s*```[^\s`]*\s*$/, '')
      .replace(/\*\*([^\n*]+)\*\*/g, '$1')
      .replace(/`([^\n`]+)`/g, '$1')
      .replace(/\[([^\]\n]+)\]\(([^\s)]+)\)/g, '$1 : $2')
      .replace(/^\s*[-*+)\s+/, '')
      .replace(/^\s*\|(.+)\|\s*$/, (_, cells) => cells.split('|').map(c => c.trim()).join(' ; '));
  }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function removePathsAndIds(text) {
  return text.replace(/\/(?:opt|home|var|usr|tmp)\/[^\s)']+/g, '<chemin>')
    .replace(/jl03-cor-p1|D0[0-9]+|D1[0-7]+/g, '<identifiant>');
}

export function prepareSpokenAnswer(res = {}) {
  const text = typeof res.answer === 'string' && res.answer.trim()
    ? res.answer : (typeof res.spoken_answer === 'string' ? res.spoken_answer : '');
  let spoken = removeMarkdown(text);
  if (!res.detailed) spoken = removePathsAndIds(spoken);
  return spoken;
}
"}
{"path": "tests/d04-daily.test.mjs", "text": "import { prepareSpokenAnswer } from '../site/spoken-answer.mjs';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import assert from 'node:assert/strict';

test('daily mode preserves errors and reservations', () => {
  const res = {
    answer: '# ÉCHEC\nRéserve : données incomplètes.',
    spoken_answer: 'Succès.'
  };
  const spoken = prepareSpokenAnswer(res);
  assert.ok(spoken.includes('ÉCHEC') && spoken.includes('Réserve'), 'errors and reservations must be audible');
});

test('daily mode omits paths and IDs unless explicitly requested', () => {
  const res = {
    answer: 'Fichier `/opt/jarvis-lab/jl03-cor-p1/D04/test.md` valide.',
    spoken_answer: 'Le fichier test.md est valide.'
  };
  const spoken = prepareSpokenAnswer(res);
  assert.ok(spoken.includes('test.md') && !spoken.includes('/opt/jarvis-lab/'), 'paths omitted by default');
});

test('explicit details mode preserves paths and IDs', () => {
  const res = {
    answer: 'Fichier `/opt/jarvis-lab/jl03-cor-p1/D04/test.md` valide.',
    spoken_answer: 'Le fichier test.md est valide.'
  };
  const spoken = prepareSpokenAnswer({ ...res, detailed: true });
  assert.ok(spoken.includes('/opt/jarvis-lab/'), 'paths preserved when detailed requested');
});
"}
